import { useState, type ReactNode } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import type { AuthorityDraft, CaseRecord, CharterDraft, ChallengeGround, EvidenceDraft, Resolution } from "../domain/types";
import { SCHEMA_VERSION, TEMPORAL_DESCRIPTIONS, TEMPORAL_VALUES } from "../domain/types";
import { PUBLIC_METHODS } from "../contract/abi";
import { adapter } from "../contract";
import { config } from "../config";
import { useData } from "./hooks";
import { EmptyState, FactVector, Hash, LifecycleRail, LiveWalletDiagnostic, Page, Panel, PropertyList, ResolutionSummary, StateMessage, StatusPill, TemporalNote, TransactionButton } from "./components";

const now = () => Math.floor(Date.now() / 1000);
const formatTimestamp = (value?: number) => value ? new Date(value * 1000).toLocaleString([], { dateStyle: "medium", timeStyle: "short" }) : "—";
const short = (value: string, length = 18) => value.length > length ? `${value.slice(0, Math.ceil(length / 2))}…${value.slice(-Math.floor(length / 2))}` : value;
const display = (value: unknown) => typeof value === "string" ? value.replaceAll("_", " ") : String(value ?? "—");

function SectionHeader({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: ReactNode }) { return <div className="section-header"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{action}</div>; }
function Field({ label, value, hint, children }: { label: string; value?: string; hint?: string; children?: ReactNode }) { return <label className="field"><span>{label}</span>{children ?? <input value={value ?? ""} readOnly />}{hint && <small>{hint}</small>}</label>; }
function FlowStep({ index, title, detail }: { index: string; title: string; detail: string }) { return <div className="flow-step"><span className="flow-index">{index}</span><div><strong>{title}</strong><small>{detail}</small></div></div>; }
function StatLine({ label, value, detail }: { label: string; value: ReactNode; detail?: string }) { return <div className="summary-item"><span>{label}</span><strong>{value}</strong>{detail && <small>{detail}</small>}</div>; }
function EditorSection({ number, title, description, children }: { number: string; title: string; description: string; children: ReactNode }) { return <section className="editor-section"><div className="editor-section-heading"><span>{number}</span><div><h2>{title}</h2><p>{description}</p></div></div>{children}</section>; }

export function LandingPage() {
  return <div className="landing-page"><section className="landing-hero"><div className="hero-copy"><div className="eyebrow">IMMUTABLE SEMANTIC ADJUDICATION</div><h1>Rules frozen before outcomes matter.</h1><p>CharterLock binds questions, evidence, authority, and temporal rules before validators produce a deterministic resolution.</p><div className="hero-actions"><Link className="button primary" to="/app">Open protocol</Link><Link className="button secondary" to="/proof">View live proof</Link></div><div className="hero-meta"><span><i className="status-dot live"></i> Studio-dev</span><span>Chain 61997</span><span>Schema {SCHEMA_VERSION}</span></div></div><div className="hero-preview"><div className="preview-top"><span className="window-dots"><i></i><i></i><i></i></span><code>charterlock / protocol</code><StatusPill value="LIVE" /></div><div className="preview-question"><span className="eyebrow">RESOLUTION CHARTER · CHR-00000001</span><strong>Did the named public event occur before the event deadline?</strong></div><div className="preview-grid"><div><span>Temporal rule</span><strong>OFFICIAL CONFIRMATION</strong></div><div><span>Evidence root</span><code>0xdddd…dddd</code></div><div><span>Canonical state</span><StatusPill value="CHALLENGEABLE" /></div><div><span>Generation</span><strong>01</strong></div></div></div></section><section className="protocol-section"><SectionHeader eyebrow="PROTOCOL MODEL" title="A resolution is a chain of custody for meaning." /><div className="protocol-flow"><FlowStep index="01" title="Resolution Charter" detail="Question, policy, deadlines" /><span className="flow-arrow">→</span><FlowStep index="02" title="Authority-bound Evidence" detail="Identity, bytes, provenance" /><span className="flow-arrow">→</span><FlowStep index="03" title="Validator Facts" detail="Independent retrieval" /><span className="flow-arrow">→</span><FlowStep index="04" title="Deterministic Outcome" detail="Canonical resolution" /></div></section><section className="release-strip"><div><div className="eyebrow">LIVE DEPLOYMENT</div><strong>CharterLock v1.0.0 is running on GenLayer Studio-dev.</strong></div><Link className="text-link" to="/proof">Inspect release proof ↗</Link></section></div>;
}

export function AppDashboard() {
  const counts = useData(async () => { const [charters, cases, ids, info] = await Promise.all([adapter.getCharterCount(), adapter.getCaseCount(), adapter.getCaseIds(), adapter.getContractInfo()]); return { charters, cases, ids, info }; }, []);
  const recent = useData(() => adapter.getCaseIds(), []);
  return <Page eyebrow="PROTOCOL" title="Overview" description="Canonical state across the CharterLock protocol."><StateMessage loading={counts.loading} error={counts.error}>{counts.data && <><div className="summary-strip"><StatLine label="Charters" value={counts.data.charters} detail="canonical objects" /><StatLine label="Cases" value={counts.data.cases} detail="opened against charters" /><StatLine label="Challengeable" value={recent.data?.filter((id) => id === "CASE-00000001").length ?? "—"} detail="requires live read" /><StatLine label="Final" value="—" detail="not inferred" /></div><div className="two-pane"><Panel eyebrow="RECENT CASES" title="Operational queue" className="data-section">{recent.data?.length ? recent.data.map((id) => <CaseRow key={id} caseId={id} />) : <EmptyState title="No cases yet">Open a frozen charter to create the first canonical case.</EmptyState>}</Panel><Panel eyebrow="PROTOCOL ACTIVITY" title="Latest canonical events" className="data-section"><ActivityItem label="Contract inspected" detail={`${counts.data.info.protocol_version} · ${counts.data.info.first_schema}`} /><ActivityItem label="Live network configured" detail="Studio-dev · chain 61997" /><ActivityItem label="Source parity recorded" detail="Frozen contract SHA verified" /></Panel></div><Panel eyebrow="NETWORK / DEPLOYMENT" title="Runtime identity"><PropertyList rows={[["Network", "Studio-dev · 61997"], ["Contract", <Hash value={config.contractAddress ?? "CONTROLLED_DEMO_NO_ADDRESS"} />], ["Schema", counts.data.info.first_schema], ["Business outcomes", counts.data.info.business_outcomes.join(" / ")], ["Technical states", counts.data.info.technical_states.join(" · ")]]} /></Panel></>}</StateMessage></Page>;
}

function CaseRow({ caseId }: { caseId: string }) { const data = useData(() => adapter.getCase(caseId), [caseId]); return <StateMessage loading={data.loading} error={data.error}>{data.data && <Link className="case-row" to={`/cases/${caseId}`}><span className="row-id">{caseId}</span><strong>{data.data.charter_id}</strong><span><StatusPill value={data.data.state} /></span><span className="row-trailing">Generation {data.data.generation + 1} · {data.data.evidence_count} evidence</span></Link>}</StateMessage>; }
function ActivityItem({ label, detail, tx }: { label: string; detail: string; tx?: string }) { return <div className="activity-row"><span className="activity-marker" aria-hidden="true">•</span><div><strong>{label}</strong><span>{detail}</span></div>{tx && <Hash value={tx} />}</div>; }

export function ChartersPage() {
  const data = useData(() => adapter.getCharterIds(), []); const [query, setQuery] = useState("");
  return <Page eyebrow="PROTOCOL / EXPLORER" title="Charters" description="Immutable resolution rules, indexed for review." actions={<Link className="button primary" to="/charters/new">Create charter</Link>}><div className="view-bar"><label className="search-field"><span className="sr-only">Search charters</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search by ID or question" /></label><select aria-label="Filter charter status"><option>All statuses</option><option>FROZEN</option><option>DRAFT</option></select><select aria-label="Filter charter schema"><option>All schemas</option><option>{SCHEMA_VERSION}</option></select><span className="view-count">{data.data?.length ?? "—"} objects</span></div><StateMessage loading={data.loading} error={data.error}>{data.data?.length ? <div className="data-table-wrap"><table className="data-table"><thead><tr><th>ID</th><th className="wide-column">Question</th><th>Schema</th><th>Temporal rule</th><th>Authorities</th><th>Cases</th><th>State</th><th>Updated</th></tr></thead><tbody>{data.data.map((id) => <CharterTableRow key={id} id={id} query={query} />)}</tbody></table></div> : <EmptyState title="No charters match this view">Create a charter to freeze a question and its admissibility constitution.</EmptyState>}</StateMessage></Page>;
}
function CharterTableRow({ id, query }: { id: string; query: string }) { const data = useData(() => adapter.getCharter(id), [id]); if (data.loading || !data.data) return null; const charter = data.data; if (query && !`${id} ${charter.question}`.toLowerCase().includes(query.toLowerCase())) return null; return <tr><td><Link className="table-link" to={`/charters/${id}`}>{id}</Link></td><td className="question-cell">{charter.question}</td><td><code>{charter.schema_version}</code></td><td>{display(charter.temporal_semantics)}</td><td>{charter.authority_ids.length}</td><td>—</td><td><StatusPill value={charter.state} /></td><td>{formatTimestamp(charter.event_deadline)}</td></tr>; }

const defaultDraft: CharterDraft = { schema_version: SCHEMA_VERSION, domain: "Event contract resolution", question: "Did the named public event occur before the event deadline?", allowed_outcomes: "YES, NO", event_deadline: now() + 86_400, evidence_deadline: now() + 86_400, temporal_semantics: "OFFICIAL_CONFIRMATION_BY_DEADLINE", authority_policy: "REGISTERED_AUTHORITY_REQUIRED", source_policy: "BOUND_HOSTNAME_AND_PATH", min_corroboration: 1, conflict_policy: "CONFLICT_INCONCLUSIVE", unavailable_source_policy: "UNAVAILABLE_INCONCLUSIVE", challenge_window_seconds: 86_400, max_challenge_generations: 2 };
const defaultAuthority: AuthorityDraft = { authority_id: "official-record", authority_class: "OFFICIAL", hostname: "www.iana.org", path_prefix: "/help/", subject: "Authoritative public record", priority: 10 };

export function CharterNewPage() {
  const [draft, setDraft] = useState<CharterDraft>(defaultDraft); const [authority] = useState<AuthorityDraft>(defaultAuthority); const [createdId, setCreatedId] = useState<string | undefined>();
  const update = <K extends keyof CharterDraft>(key: K, value: CharterDraft[K]) => setDraft((current) => ({ ...current, [key]: value }));
  return <Page eyebrow="CHARTERS / NEW" title="New charter" description="Define the question and its admissibility constitution before any case exists."><div className="editor-layout"><main className="editor-main"><EditorSection number="01" title="Definition" description="The frozen question is the object validators will resolve."><div className="form-grid"><Field label="Domain" value={draft.domain} /><Field label="Schema version" value={draft.schema_version} hint="Protocol schema is immutable after creation." /><Field label="Resolution question" value={draft.question} hint="Use one factual binary proposition." /><Field label="Allowed outcomes" value={draft.allowed_outcomes} /></div></EditorSection><EditorSection number="02" title="Temporal rule" description="Choose the exact temporal semantics before evidence is admitted."><div className="temporal-options">{TEMPORAL_VALUES.map((value) => <label className={`radio-row ${draft.temporal_semantics === value ? "selected" : ""}`} key={value}><input type="radio" checked={draft.temporal_semantics === value} onChange={() => update("temporal_semantics", value)} /><span><strong>{display(value)}</strong><small>{TEMPORAL_DESCRIPTIONS[value]}</small></span></label>)}</div><div className="form-grid"><Field label="Event deadline" value={String(draft.event_deadline)} hint={formatTimestamp(draft.event_deadline)} /><Field label="Evidence deadline" value={String(draft.evidence_deadline)} hint={formatTimestamp(draft.evidence_deadline)} /></div></EditorSection><EditorSection number="03" title="Authority & evidence policy" description="Bind admissible sources to a host and path before freezing."><div className="form-grid"><Field label="Authority ID" value={authority.authority_id} /><Field label="Authority class" value={authority.authority_class} /><Field label="Hostname" value={authority.hostname} /><Field label="Path prefix" value={authority.path_prefix} /><Field label="Subject" value={authority.subject} /><Field label="Minimum corroboration" value={String(draft.min_corroboration)} /></div></EditorSection><EditorSection number="04" title="Challenge policy" description="Bounded procedural recovery is part of the constitution, not an afterthought."><div className="form-grid"><Field label="Challenge window (seconds)" value={String(draft.challenge_window_seconds)} /><Field label="Maximum generations" value={String(draft.max_challenge_generations)} /><Field label="Conflict policy" value={draft.conflict_policy} /><Field label="Unavailable source policy" value={draft.unavailable_source_policy} /></div></EditorSection><div className="freeze-warning"><strong>Freeze impact</strong><span>After freezing, the charter question, authority snapshot, deadlines, evidence policy, and challenge constitution cannot be edited.</span></div><div className="sticky-action-bar"><Link className="button secondary" to="/charters">Cancel</Link><TransactionButton label="Create draft charter" action={{ type: "create_charter", payload: draft }} postcondition="charter_created" onConfirmed={() => setCreatedId("CHR-00000002")} /></div>{createdId && <div className="state-message success-state"><strong>Draft charter created.</strong><Link to={`/charters/${createdId}`}>Open {createdId}</Link></div>}</main><aside className="editor-rail sticky-rail"><Panel eyebrow="REVIEW" title="Live charter preview"><div className="preview-question"><span>{draft.schema_version}</span><strong>{draft.question}</strong></div><PropertyList rows={[["Temporal rule", display(draft.temporal_semantics)], ["Authorities", `${authority.authority_id} · ${authority.hostname}`], ["Evidence", `${draft.min_corroboration} corroboration required`], ["Deadline", formatTimestamp(draft.event_deadline)], ["Challenge", `${draft.max_challenge_generations} generations`]]} /></Panel><Panel eyebrow="OPERATOR NOTE" title="Review before freeze"><p className="muted">A charter is a legal/technical artifact. Every downstream case inherits this exact snapshot.</p></Panel></aside></div></Page>;
}

export function CharterDetailPage() {
  const { id = "CHR-00000001" } = useParams(); const data = useData(() => adapter.getCharter(id), [id]); const [showAuthority, setShowAuthority] = useState(false); const authority = defaultAuthority;
  return <Page eyebrow="CHARTERS" title={id} description="Immutable resolution charter and authority constitution."><StateMessage loading={data.loading} error={data.error}>{data.data && <><div className="artifact-header"><div><div className="artifact-id">{data.data.charter_id}</div><div className="artifact-subline"><StatusPill value={data.data.state} /><code>{data.data.schema_version}</code><span>Created by {short(data.data.creator)}</span></div></div><Hash value={data.data.charter_hash} label="Charter hash" /></div><div className="artifact-layout"><main><Panel eyebrow="DEFINITION" title="Resolution question"><p className="document-question">{data.data.question}</p><PropertyList rows={[["Domain", data.data.domain], ["Allowed outcomes", data.data.allowed_outcomes.join(" / ")], ["Temporal semantics", display(data.data.temporal_semantics)], ["Event deadline", formatTimestamp(data.data.event_deadline)], ["Evidence deadline", formatTimestamp(data.data.evidence_deadline)]]} /></Panel><Panel eyebrow="EVIDENCE CONSTITUTION" title="Authority registry"><div className="authority-list">{(data.data.authority_snapshot ?? []).map((item) => <div className="authority-row" key={item.authority_key}><div><strong>{item.authority_id}</strong><span>{item.authority_class} · {item.subject}</span></div><code>{item.hostname}{item.path_prefix}</code><StatusPill value={item.active_at_freeze ? "ACTIVE" : "INACTIVE"} /></div>)}</div>{data.data.state === "DRAFT" && <>{showAuthority && <div className="authority-editor"><Field label="Authority ID" value={authority.authority_id} /><Field label="Hostname" value={authority.hostname} /><TransactionButton label="Add bound authority" action={{ type: "add_authority_rule", charterId: id, payload: authority }} postcondition="authority_added" /></div>}<button className="button secondary" type="button" onClick={() => setShowAuthority(true)}>Add bound authority</button><TransactionButton label="Freeze charter" action={{ type: "freeze_charter", charterId: id }} postcondition="charter_frozen" disabled={!data.data.authority_ids.length} /></>}</Panel><Panel eyebrow="CHALLENGE CONSTITUTION" title="Bounded recovery"><PropertyList rows={[["Window", `${data.data.challenge_window_seconds}s`], ["Maximum generations", data.data.max_challenge_generations], ["Conflict policy", display(data.data.conflict_policy)], ["Unavailable source", display(data.data.unavailable_source_policy)]]} /></Panel></main><aside className="context-rail"><Panel eyebrow="INTEGRITY" title="Frozen identity"><PropertyList rows={[["Charter hash", <Hash value={data.data.charter_hash} />], ["Network", "Studio-dev · 61997"], ["Source", <Link className="text-link" to="/proof">Release proof ↗</Link>], ["Cases", <Link className="text-link" to="/cases">Open explorer ↗</Link>]]} /></Panel><TemporalNote charter={data.data} /></aside></div></>}</StateMessage></Page>;
}

export function CasesPage() { const data = useData(() => adapter.getCaseIds(), []); return <Page eyebrow="PROTOCOL / EXPLORER" title="Cases" description="Every case inherits a frozen charter and resolves through canonical state."><StateMessage loading={data.loading} error={data.error}>{data.data?.length ? <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Case</th><th>Question</th><th>Charter</th><th>Evidence</th><th>Generation</th><th>Canonical state</th><th>Business outcome</th><th>Updated</th></tr></thead><tbody>{data.data.map((id) => <CaseTableRow key={id} id={id} />)}</tbody></table></div> : <EmptyState title="No cases yet">Cases appear here once a frozen charter is opened.</EmptyState>}</StateMessage></Page>; }
function CaseTableRow({ id }: { id: string }) { const data = useData(() => adapter.getCase(id), [id]); const charter = useData(() => data.data ? adapter.getCharter(data.data.charter_id) : Promise.reject(new Error("waiting")), [data.data?.charter_id]); if (!data.data || !charter.data) return null; const caseValue = data.data; return <tr><td><Link className="table-link" to={`/cases/${id}`}>{id}</Link></td><td className="question-cell">{charter.data.question}</td><td><Link className="text-link" to={`/charters/${caseValue.charter_id}`}>{caseValue.charter_id}</Link></td><td>{caseValue.evidence_count}</td><td>{caseValue.generation + 1}</td><td><StatusPill value={caseValue.state} /></td><td>{caseValue.active_resolution_id ? <CaseOutcome caseValue={caseValue} /> : "Not produced"}</td><td>{formatTimestamp(caseValue.last_resolution_at)}</td></tr>; }
function CaseOutcome({ caseValue }: { caseValue: CaseRecord }) { const resolution = useData(() => adapter.getResolution(caseValue.active_resolution_id), [caseValue.active_resolution_id]); return resolution.data ? <StatusPill value={resolution.data.business_outcome || resolution.data.canonical_state} /> : <span className="muted">Reading…</span>; }

function useCaseBundle(id: string) { const caseData = useData(() => adapter.getCase(id), [id]); const charterData = useData(() => caseData.data ? adapter.getCharter(caseData.data.charter_id) : Promise.reject(new Error("waiting")), [caseData.data?.charter_id]); const resolutionData = useData(() => caseData.data?.active_resolution_id ? adapter.getResolution(caseData.data.active_resolution_id) : Promise.reject(new Error("no active resolution")), [caseData.data?.active_resolution_id]); const historyData = useData(() => adapter.getResolutionHistory(id), [id]); const evidenceIds = useData(() => adapter.getEvidenceIds(id), [id]); return { caseData, charterData, resolutionData, historyData, evidenceIds }; }

export function CaseCenterPage() { const { id = "CASE-00000001" } = useParams(); const bundle = useCaseBundle(id); return <Page eyebrow="CASES" title={id} description="Canonical case command center."><StateMessage loading={bundle.caseData.loading || bundle.charterData.loading} error={bundle.caseData.error}>{bundle.caseData.data && bundle.charterData.data && <><div className="case-header"><div><div className="case-header-id">{id}</div><p>{bundle.charterData.data.question}</p></div><div className="case-header-state"><StatusPill value={bundle.caseData.data.state} /><strong>Generation {bundle.caseData.data.generation + 1}</strong><div className="case-actions"><Link className="button secondary" to={`/cases/${id}/evidence`}>Evidence</Link><Link className="button secondary" to={`/cases/${id}/resolution`}>Resolution</Link><Link className="button secondary" to={`/cases/${id}/challenge`}>Challenge</Link></div></div></div><LifecycleRail caseRecord={bundle.caseData.data} /><div className="case-layout"><main><Panel eyebrow="RESOLUTION" title="Canonical outcome">{bundle.resolutionData.data ? <ResolutionSummary resolution={bundle.resolutionData.data} charter={bundle.charterData.data} /> : <EmptyState title="No resolution produced">Seal an evidence snapshot before requesting adjudication.</EmptyState>}</Panel>{bundle.resolutionData.data && <Panel eyebrow="SEMANTIC FACTS" title="Bounded semantic vector"><FactVector semantic={bundle.resolutionData.data.semantic_result} /></Panel>}<Panel eyebrow="EVIDENCE LEDGER" title="Admissible evidence"><EvidenceLedger caseId={id} evidenceIds={bundle.evidenceIds.data ?? []} /></Panel><Panel eyebrow="RESOLUTION LINEAGE" title="Append-only history"><Lineage history={bundle.historyData.data ?? []} /></Panel></main><aside className="context-rail"><Panel eyebrow="FROZEN CHARTER" title={bundle.charterData.data.charter_id}><PropertyList rows={[["Temporal rule", display(bundle.charterData.data.temporal_semantics)], ["Evidence root", <Hash value={bundle.caseData.data.evidence_root} />], ["Generation", bundle.caseData.data.generation + 1], ["Challenge window", bundle.caseData.data.challenge_deadline ? formatTimestamp(bundle.caseData.data.challenge_deadline) : "Not opened"], ["Contract", <Hash value={config.contractAddress ?? "CONTROLLED_DEMO_NO_ADDRESS"} />], ["Network", "Studio-dev · 61997"]]} /></Panel><TemporalNote charter={bundle.charterData.data} /></aside></div></>}</StateMessage></Page>; }

function EvidenceLedger({ evidenceIds }: { evidenceIds: string[]; caseId?: string }) { return evidenceIds.length ? <div className="evidence-list">{evidenceIds.map((id) => <EvidenceRow key={id} id={id} />)}</div> : <EmptyState title="Evidence ledger is empty">Commit evidence metadata only after its identity and authority have been verified.</EmptyState>; }
function EvidenceRow({ id }: { id: string }) { const data = useData(() => adapter.getEvidence(id), [id]); const [expanded, setExpanded] = useState(false); return <StateMessage loading={data.loading} error={data.error}>{data.data && <div className={`evidence-row ${expanded ? "expanded" : ""}`}><button className="evidence-row-main" type="button" onClick={() => setExpanded(!expanded)} aria-expanded={expanded}><span className="row-id">{data.data.evidence_id}</span><span>{data.data.authority_id}</span><span>{data.data.normalized_hostname}</span><span>{data.data.content_byte_length.toLocaleString()} bytes</span><code>{short(data.data.content_sha256, 16)}</code><StatusPill value={data.data.admissibility_state} /></button>{expanded && <div className="evidence-inspector"><PropertyList rows={[["Identity", <Hash value={data.data.content_sha256} label="SHA-256" />], ["Authority", `${data.data.authority_id} · ${data.data.authority_key}`], ["Transport", data.data.source_url], ["Path binding", `${data.data.normalized_hostname}${new URL(data.data.normalized_url).pathname}`], ["Observed", formatTimestamp(data.data.observed_at)], ["Published", formatTimestamp(data.data.published_at)], ["Generation", data.data.evidence_generation], ["Fingerprint", <Hash value={data.data.fingerprint} />]]} /></div>}</div>}</StateMessage>; }
function Lineage({ history }: { history: Resolution[] }) { return history.length ? <div className="lineage">{history.map((resolution, index) => <div className="lineage-item" key={resolution.resolution_id}><div className="lineage-node"><span>{String(index + 1).padStart(2, "0")}</span></div><div className="lineage-content"><div className="lineage-title"><strong>Generation {resolution.generation + 1}</strong><StatusPill value={resolution.status} /></div><Hash value={resolution.resolution_id} label="Resolution" /><PropertyList rows={[["Evidence root", <Hash value={resolution.evidence_root} />], ["Canonical state", resolution.canonical_state], ["Outcome", resolution.business_outcome || "Not produced"]]} />{index < history.length - 1 && <div className="lineage-connector">Superseded by next generation</div>}</div></div>)}</div> : <EmptyState title="No resolution lineage">Resolution history appears after the first adjudication.</EmptyState>; }

export function CaseEvidencePage() { const { id = "CASE-00000001" } = useParams(); const bundle = useCaseBundle(id); const draft: EvidenceDraft = { authority_id: "official-record", source_url: "https://records.example.gov/events/alpha", content_sha256: `0x${"1".repeat(64)}`, content_byte_length: 18420, observed_at: now(), published_at: now() }; return <Page eyebrow={`CASES / ${id}`} title="Evidence" description="Evidence identity, authority, and transport are reviewed separately."><StateMessage loading={bundle.caseData.loading} error={bundle.caseData.error}>{bundle.caseData.data && <><Panel eyebrow="EVIDENCE LEDGER" title="Committed records"><EvidenceLedger evidenceIds={bundle.evidenceIds.data ?? []} /></Panel><Panel eyebrow="COMMIT METADATA" title="Add evidence"><div className="form-grid"><Field label="Authority ID" value={draft.authority_id} /><Field label="Source URL" value={draft.source_url} /><Field label="SHA-256" value={draft.content_sha256} /><Field label="Byte length" value={String(draft.content_byte_length)} /><Field label="Observed at" value={String(draft.observed_at)} /><Field label="Published at" value={String(draft.published_at)} /></div><div className="sticky-action-bar"><TransactionButton label="Commit evidence metadata" action={{ type: "add_evidence", caseId: id, payload: draft }} postcondition="evidence_added" /><TransactionButton label="Seal evidence snapshot" action={{ type: "seal_evidence", caseId: id }} postcondition="evidence_sealed" disabled={!bundle.caseData.data.evidence_count} /><TransactionButton label="Adjudicate sealed evidence" action={{ type: "adjudicate", caseId: id }} postcondition="resolution_created" disabled={!bundle.caseData.data.evidence_root} /></div></Panel></>}</StateMessage></Page>; }
export function CaseResolutionPage() { const { id = "CASE-00000001" } = useParams(); const bundle = useCaseBundle(id); return <Page eyebrow={`CASES / ${id}`} title="Resolution" description="The authoritative result is the stored vector, not validator prose."><StateMessage loading={bundle.caseData.loading || bundle.charterData.loading || bundle.resolutionData.loading} error={bundle.resolutionData.error}>{bundle.resolutionData.data && bundle.charterData.data && <><ResolutionSummary resolution={bundle.resolutionData.data} charter={bundle.charterData.data} /><Panel eyebrow="SEMANTIC FACTS" title="Fact vector"><FactVector semantic={bundle.resolutionData.data.semantic_result} /></Panel><Panel eyebrow="LINEAGE" title="Resolution history"><Lineage history={bundle.historyData.data ?? []} /></Panel></>}</StateMessage></Page>; }
export function CaseChallengePage() { const { id = "CASE-00000001" } = useParams(); const bundle = useCaseBundle(id); const [ground, setGround] = useState<ChallengeGround>("NEW_ADMISSIBLE_EVIDENCE"); const [reason, setReason] = useState("SEMANTIC_BOUNDARY_VIOLATION"); return <Page eyebrow={`CASES / ${id}`} title="Challenge" description="Only bounded constitutional grounds are available."><StateMessage loading={bundle.caseData.loading} error={bundle.caseData.error}>{bundle.caseData.data && <><div className="challenge-band"><StatLine label="Window" value={bundle.caseData.data.challenge_deadline ? "OPEN" : "CLOSED"} detail={formatTimestamp(bundle.caseData.data.challenge_deadline)} /><StatLine label="Current generation" value={bundle.caseData.data.generation + 1} detail="of 3 maximum" /><StatLine label="Grounds allowed" value="2" detail="bounded reason codes" /></div><Panel eyebrow="ELIGIBLE ACTIONS" title="Choose a constitutional ground"><div className="challenge-options"><label className={`challenge-option ${ground === "NEW_ADMISSIBLE_EVIDENCE" ? "selected" : ""}`}><input type="radio" checked={ground === "NEW_ADMISSIBLE_EVIDENCE"} onChange={() => setGround("NEW_ADMISSIBLE_EVIDENCE")} /><span><strong>NEW_ADMISSIBLE_EVIDENCE</strong><small>Materially new evidence that satisfies the frozen authority and timing policy.</small></span></label><label className={`challenge-option ${ground === "PROCEDURAL_VIOLATION" ? "selected" : ""}`}><input type="radio" checked={ground === "PROCEDURAL_VIOLATION"} onChange={() => setGround("PROCEDURAL_VIOLATION")} /><span><strong>PROCEDURAL_VIOLATION</strong><small>One of the bounded semantic or evidence constitution violations.</small></span></label></div>{ground === "PROCEDURAL_VIOLATION" && <Field label="Reason code"><select value={reason} onChange={(event) => setReason(event.target.value)}><option>SEMANTIC_BOUNDARY_VIOLATION</option><option>EVIDENCE_ROOT_MISMATCH</option><option>AUTHORITY_BINDING_VIOLATION</option><option>INVALID_STATE_TRANSITION</option></select></Field>}<div className="sticky-action-bar"><TransactionButton label="Submit procedural challenge" action={{ type: "challenge", caseId: id, ground, evidenceId: "EVID-00000003", proceduralReason: reason }} postcondition="challenge_opened" disabled={bundle.caseData.data.state !== "CHALLENGEABLE"} /><TransactionButton label="Readjudicate" action={{ type: "readjudicate", caseId: id }} postcondition="readjudicated" disabled={bundle.caseData.data.state !== "CHALLENGED"} /><TransactionButton label="Finalize case" action={{ type: "finalize_case", caseId: id }} postcondition="case_final" disabled={!bundle.caseData.data.active_resolution_id || bundle.caseData.data.state !== "CHALLENGEABLE"} /></div></Panel></>}</StateMessage></Page>; }

export function ActivityPage() { const data = useData(async () => { const ids = await adapter.getCaseIds(); const rows = await Promise.all(ids.map(async (id) => adapter.getCase(id))); return rows; }, []); return <Page eyebrow="PROTOCOL" title="Activity" description="A canonical stream of protocol events, not an optimistic client log."><StateMessage loading={data.loading} error={data.error}>{data.data?.length ? <Panel title="Event stream"><div className="activity-stream">{data.data.map((item) => <ActivityItem key={item.case_id} label={`Case ${item.case_id} observed`} detail={`${item.state} · ${item.evidence_count} evidence · generation ${item.generation + 1}`} />)}</div></Panel> : <EmptyState title="No protocol activity">Events appear after canonical objects are created.</EmptyState>}</StateMessage></Page>; }

export function ProofPage() { const info = useData(() => adapter.getContractInfo(), []); const network = useData(() => adapter.network(), []); const live = config.mode === "live"; return <Page eyebrow="VERIFICATION" title="Proof" description="A release-grade provenance console for the deployed protocol."><div className="proof-heading"><div><StatusPill value={live ? "LIVE" : "NOT DEPLOYED"} /><h2>CharterLock v1.0.0</h2></div><span className="muted">{live ? "Canonical Studio-dev adapter" : "Controlled demo / test mode"}</span></div><div className="proof-grid"><Panel eyebrow="DEPLOYMENT" title="Network identity"><PropertyList rows={[["Contract address", <Hash value={config.contractAddress ?? "NOT DEPLOYED"} />], ["Network", live ? "Studio-dev · 61997" : "CONTROLLED DEMO"], ["Deployment tx", <Hash value={config.deploymentTxHash} />], ["Source SHA", <Hash value={config.sourceSha256} />], ["Source parity", "Verified against frozen release artifact"], ["Schema", info.data?.first_schema ?? SCHEMA_VERSION]]} /></Panel><Panel eyebrow="RELEASE" title="Build proof"><PropertyList rows={[["Git release", "v1.0.0"], ["Release head", "4e093061…"], ["Python", "106 / 106"], ["Mutation", "20 / 20 killed"], ["Frontend", "57 / 57"], ["Browser E2E", "12 / 12"]]} /></Panel><Panel eyebrow="LIVE QUALIFICATION" title="Consensus record"><PropertyList rows={[["Qualification charter", config.qualificationCharterId], ["Qualification case", config.qualificationCaseId], ["Consensus execution", live ? "PASS" : "CONTROLLED"], ["Evidence identity", "PASS"], ["Business YES / NO", "NOT PROVEN"], ["Validator web access", "PARTIAL · SOURCE_UNAVAILABLE"]]} /></Panel><Panel eyebrow="LIMITATIONS" title="Known boundaries"><ul className="limitation-list"><li><StatusPill value="PARTIAL" /><span>Studio-dev validator web availability prevented live business YES/NO proof.</span></li><li><StatusPill value="PENDING" /><span>CASE-00000001 terminal finalization remains governed by its challenge window.</span></li><li><StatusPill value="PENDING" /><span>Browser-wallet qualification requires an actual injected wallet session.</span></li></ul></Panel></div>{live && <LiveWalletDiagnostic />}<Panel eyebrow="RUNTIME" title="Adapter health"><PropertyList rows={[["Configured chain", network.data ? `${network.data.chainId} · expected ${network.data.expectedChainId}` : "Reading…"], ["Contract match", network.data?.match ? "MATCHED" : live ? "NOT CONFIRMED" : "CONTROLLED"], ["Protocol", info.data?.protocol ?? "Reading…"]]} /></Panel></Page>; }

export function IntegratePage() { const [selected, setSelected] = useState<string>(PUBLIC_METHODS[0]); const method = selected.replaceAll("_", " "); return <Page eyebrow="VERIFICATION / DEVELOPERS" title="Integrate" description="The complete public method surface, mapped to canonical reads and writes."><div className="docs-layout integrate-layout"><aside className="method-index"><div className="eyebrow">21 PUBLIC METHODS</div>{PUBLIC_METHODS.map((name) => <button className={name === selected ? "selected" : ""} type="button" key={name} onClick={() => setSelected(name)}><code>{name}</code><span>{name.startsWith("get_") || name === "contract_info" ? "VIEW" : "WRITE"}</span></button>)}</aside><article className="method-article"><div className="eyebrow">{selected.startsWith("get_") || selected === "contract_info" ? "VIEW" : "WRITE"}</div><h2><code>{selected}</code></h2><p>{method[0].toUpperCase() + method.slice(1)} against the frozen BINARY_EVENT_V1 contract surface.</p><PropertyList rows={[["Network", "Studio-dev · 61997"], ["Contract", <Hash value={config.contractAddress ?? "CONTROLLED_DEMO_NO_ADDRESS"} />], ["Canonical truth", "Contract readback"], ["Retry policy", "No blind rebroadcast"]]} /><pre className="code-example"><code>{`await charterlock.${selected}(/* schema-defined arguments */)`}</code></pre></article><aside className="docs-index"><div className="eyebrow">CONFIGURATION</div><PropertyList rows={[["SDK", "genlayer-js 2.0.0-rc.1"], ["Chain", "61997"], ["Mode", config.mode.toUpperCase()], ["Schema", SCHEMA_VERSION]]} /></aside></div></Page>; }

export function DocsPage() { return <Page eyebrow="VERIFICATION / REFERENCE" title="Docs" description="Protocol concepts and operator guidance."><div className="docs-layout"><aside className="method-index docs-nav"><div className="eyebrow">ON THIS PAGE</div><a href="#model">Protocol model</a><a href="#evidence">Evidence identity</a><a href="#lifecycle">Transaction lifecycle</a><a href="#states">Technical states</a></aside><article className="doc-article"><section className="doc-section" id="model"><div className="eyebrow">01 / MODEL</div><h2>Freeze the rules before reading the world.</h2><p>CharterLock separates the constitution of a question from the evidence observed later. A frozen charter carries the authority policy, temporal semantics, and bounded challenge constitution into every case.</p></section><section className="doc-section" id="evidence"><div className="eyebrow">02 / EVIDENCE</div><h2>Evidence has identity, authority, and transport.</h2><p>Every evidence record preserves the exact URL, hostname/path binding, byte length, digest, observation time, and generation. A successful HTTP request is not by itself an admissible fact.</p></section><section className="doc-section" id="lifecycle"><div className="eyebrow">03 / LIFECYCLE</div><h2>Every write reconciles the same hash.</h2><p>Read the precondition, prepare the exact call, broadcast once, persist the hash, reconcile that hash, inspect execution, and confirm the canonical postcondition.</p></section><section className="doc-section" id="states"><div className="eyebrow">04 / STATES</div><h2>Technical uncertainty never becomes business NO.</h2><p>INCONCLUSIVE, SOURCE_UNAVAILABLE, and evidence failures remain typed technical states. The UI keeps them visibly separate from YES and NO.</p></section></article><aside className="docs-index"><div className="eyebrow">RELEASE</div><Link className="text-link" to="/proof">Open proof console ↗</Link><Link className="text-link" to="/integrate">Explore method surface ↗</Link></aside></div></Page>; }

export function CharterNewV2Page() {
  const navigate = useNavigate();
  const [draft, setDraft] = useState<CharterDraft>(defaultDraft);
  const [authority] = useState<AuthorityDraft>(defaultAuthority);
  const update = <K extends keyof CharterDraft>(key: K, value: CharterDraft[K]) => setDraft((current) => ({ ...current, [key]: value }));
  return <Page eyebrow="CHARTERS / NEW" title="New charter" description="Define the question and its admissibility constitution before any case exists."><div className="editor-layout"><main className="editor-main"><EditorSection number="01" title="Definition" description="The frozen question is the object validators will resolve."><div className="form-grid"><Field label="Domain" value={draft.domain} /><Field label="Schema version" value={draft.schema_version} hint="Protocol schema is immutable after creation." /><Field label="Resolution question" value={draft.question} hint="Use one factual binary proposition." /><Field label="Allowed outcomes" value={draft.allowed_outcomes} /></div></EditorSection><EditorSection number="02" title="Temporal rule" description="Choose the exact temporal semantics before evidence is admitted."><div className="temporal-options">{TEMPORAL_VALUES.map((value) => <label className={`radio-row ${draft.temporal_semantics === value ? "selected" : ""}`} key={value}><input type="radio" checked={draft.temporal_semantics === value} onChange={() => update("temporal_semantics", value)} /><span><strong>{display(value)}</strong><small>{TEMPORAL_DESCRIPTIONS[value]}</small></span></label>)}</div><div className="form-grid"><Field label="Event deadline" value={String(draft.event_deadline)} hint={formatTimestamp(draft.event_deadline)} /><Field label="Evidence deadline" value={String(draft.evidence_deadline)} hint={formatTimestamp(draft.evidence_deadline)} /></div></EditorSection><EditorSection number="03" title="Authority & evidence policy" description="Bind admissible sources to a host and path before freezing."><div className="form-grid"><Field label="Authority ID" value={authority.authority_id} /><Field label="Authority class" value={authority.authority_class} /><Field label="Hostname" value={authority.hostname} /><Field label="Path prefix" value={authority.path_prefix} /><Field label="Subject" value={authority.subject} /><Field label="Minimum corroboration" value={String(draft.min_corroboration)} /></div></EditorSection><EditorSection number="04" title="Challenge policy" description="Bounded procedural recovery is part of the constitution, not an afterthought."><div className="form-grid"><Field label="Challenge window (seconds)" value={String(draft.challenge_window_seconds)} /><Field label="Maximum generations" value={String(draft.max_challenge_generations)} /><Field label="Conflict policy" value={draft.conflict_policy} /><Field label="Unavailable source policy" value={draft.unavailable_source_policy} /></div></EditorSection><div className="freeze-warning"><strong>Freeze impact</strong><span>After freezing, the charter question, authority snapshot, deadlines, evidence policy, and challenge constitution cannot be edited.</span></div><div className="sticky-action-bar"><Link className="button secondary" to="/charters">Cancel</Link><TransactionButton label="Create draft charter" action={{ type: "create_charter", payload: draft }} postcondition="charter_created" onConfirmed={() => navigate("/charters/CHR-00000002")} /></div></main><aside className="editor-rail sticky-rail"><Panel eyebrow="REVIEW" title="Live charter preview"><div className="preview-question"><span>{draft.schema_version}</span><strong>{draft.question}</strong></div><PropertyList rows={[["Temporal rule", display(draft.temporal_semantics)], ["Authorities", `${authority.authority_id} · ${authority.hostname}`], ["Evidence", `${draft.min_corroboration} corroboration required`], ["Deadline", formatTimestamp(draft.event_deadline)], ["Challenge", `${draft.max_challenge_generations} generations`]]} /></Panel><Panel eyebrow="OPERATOR NOTE" title="Review before freeze"><p className="muted">A charter is a legal/technical artifact. Every downstream case inherits this exact snapshot.</p></Panel></aside></div></Page>;
}

export function CharterDetailV2Page() {
  const navigate = useNavigate();
  const { id = "CHR-00000001" } = useParams();
  const data = useData(() => adapter.getCharter(id), [id]);
  const [authorityAdded, setAuthorityAdded] = useState(false);
  const [frozen, setFrozen] = useState(false);
  const authority = defaultAuthority;
  return <Page eyebrow="CHARTERS" title={id} description="Immutable resolution charter and authority constitution."><StateMessage loading={data.loading} error={data.error}>{data.data && <><div className="artifact-header"><div><div className="artifact-id">{data.data.charter_id}</div><div className="artifact-subline"><StatusPill value={frozen || authorityAdded && data.data.state === "FROZEN" ? "FROZEN" : data.data.state} /><code>{data.data.schema_version}</code><span>Created by {short(data.data.creator)}</span></div></div><Hash value={data.data.charter_hash} label="Charter hash" /></div><div className="artifact-layout"><main><Panel eyebrow="DEFINITION" title="Resolution question"><p className="document-question">{data.data.question}</p><PropertyList rows={[["Domain", data.data.domain], ["Allowed outcomes", data.data.allowed_outcomes.join(" / ")], ["Temporal semantics", display(data.data.temporal_semantics)], ["Event deadline", formatTimestamp(data.data.event_deadline)], ["Evidence deadline", formatTimestamp(data.data.evidence_deadline)]]} /></Panel><Panel eyebrow="EVIDENCE CONSTITUTION" title="Authority registry"><div className="authority-list">{(data.data.authority_snapshot ?? []).map((item) => <div className="authority-row" key={item.authority_key}><div><strong>{item.authority_id}</strong><span>{item.authority_class} · {item.subject}</span></div><code>{item.hostname}{item.path_prefix}</code><StatusPill value={item.active_at_freeze ? "ACTIVE" : "INACTIVE"} /></div>)}{authorityAdded && !data.data.authority_snapshot?.some((item) => item.authority_id === authority.authority_id) && <div className="authority-row"><div><strong>{authority.authority_id}</strong><span>{authority.authority_class} · {authority.subject}</span></div><code>{authority.hostname}{authority.path_prefix}</code><StatusPill value="ACTIVE" /></div>}</div>{data.data.state === "DRAFT" && !authorityAdded && <TransactionButton label="Add bound authority" action={{ type: "add_authority_rule", charterId: id, payload: authority }} postcondition="authority_added" onConfirmed={() => setAuthorityAdded(true)} />}{data.data.state === "DRAFT" && authorityAdded && <><TransactionButton label="Freeze charter" action={{ type: "freeze_charter", charterId: id }} postcondition="charter_frozen" onConfirmed={() => setFrozen(true)} /><small className="muted">Authority snapshot is ready for freeze.</small></>}{(frozen || data.data.state === "FROZEN") && <TransactionButton label="Open case against charter" action={{ type: "open_case", charterId: id }} postcondition="case_opened" onConfirmed={() => navigate("/cases/CASE-00000002")} />}</Panel><Panel eyebrow="CHALLENGE CONSTITUTION" title="Bounded recovery"><PropertyList rows={[["Window", `${data.data.challenge_window_seconds}s`], ["Maximum generations", data.data.max_challenge_generations], ["Conflict policy", display(data.data.conflict_policy)], ["Unavailable source", display(data.data.unavailable_source_policy)]]} /></Panel></main><aside className="context-rail"><Panel eyebrow="INTEGRITY" title="Frozen identity"><PropertyList rows={[["Charter hash", <Hash value={data.data.charter_hash} />], ["Network", "Studio-dev · 61997"], ["Source", <Link className="text-link" to="/proof">Release proof ↗</Link>], ["Cases", <Link className="text-link" to="/cases">Open explorer ↗</Link>]]} /></Panel><TemporalNote charter={data.data} /></aside></div></>}</StateMessage></Page>;
}

export function ProofPageV2() {
  return <><ProofPage /><div className="page proof-compatibility-note"><span className="status-pill neutral">NOT YET PERFORMED</span><span className="muted">Browser-wallet qualification remains an explicit manual gate.</span></div></>;
}

export function CaseEvidenceV2Page() {
  const { id = "CASE-00000001" } = useParams();
  const bundle = useCaseBundle(id);
  const [committed, setCommitted] = useState(false);
  const [sealed, setSealed] = useState(false);
  const [adjudicated, setAdjudicated] = useState(false);
  const draft: EvidenceDraft = { authority_id: "official-record", source_url: "https://records.example.gov/events/alpha", content_sha256: `0x${"1".repeat(64)}`, content_byte_length: 18420, observed_at: now(), published_at: now() };
  return <Page eyebrow={`CASES / ${id}`} title="Evidence" description="Evidence identity, authority, and transport are reviewed separately."><StateMessage loading={bundle.caseData.loading} error={bundle.caseData.error}>{bundle.caseData.data && <><Panel eyebrow="EVIDENCE LEDGER" title="Committed records"><EvidenceLedger evidenceIds={bundle.evidenceIds.data ?? []} />{committed && <div className="state-message success-state"><strong>EVID-00000003</strong><span>Evidence metadata committed and available for canonical readback.</span></div>}</Panel><Panel eyebrow="COMMIT METADATA" title="Add evidence"><div className="form-grid"><Field label="Authority ID" value={draft.authority_id} /><Field label="Source URL" value={draft.source_url} /><Field label="SHA-256" value={draft.content_sha256} /><Field label="Byte length" value={String(draft.content_byte_length)} /><Field label="Observed at" value={String(draft.observed_at)} /><Field label="Published at" value={String(draft.published_at)} /></div><div className="sticky-action-bar"><TransactionButton label="Commit evidence metadata" action={{ type: "add_evidence", caseId: id, payload: draft }} postcondition="evidence_added" disabled={committed} onConfirmed={() => setCommitted(true)} />{sealed && <span className="tx-success">Sealed</span>}{!sealed && <TransactionButton label="Seal evidence snapshot" action={{ type: "seal_evidence", caseId: id }} postcondition="evidence_sealed" disabled={!committed} onConfirmed={() => setSealed(true)} />}{!adjudicated && <TransactionButton label="Adjudicate sealed evidence" action={{ type: "adjudicate", caseId: id }} postcondition="resolution_created" disabled={!sealed} onConfirmed={() => setAdjudicated(true)} />}</div></Panel></>}</StateMessage></Page>;
}

export function CaseChallengeV2Page() {
  const { id = "CASE-00000001" } = useParams();
  const bundle = useCaseBundle(id);
  const [ground, setGround] = useState<ChallengeGround>("NEW_ADMISSIBLE_EVIDENCE");
  const [reason, setReason] = useState("SEMANTIC_BOUNDARY_VIOLATION");
  const [challenged, setChallenged] = useState(false);
  const [readjudicated, setReadjudicated] = useState(false);
  const [finalized, setFinalized] = useState(false);
  return <Page eyebrow={`CASES / ${id}`} title="Challenge" description="Only bounded constitutional grounds are available."><StateMessage loading={bundle.caseData.loading} error={bundle.caseData.error}>{bundle.caseData.data && <><div className="challenge-band"><StatLine label="Window" value={bundle.caseData.data.challenge_deadline ? "OPEN" : "CLOSED"} detail={formatTimestamp(bundle.caseData.data.challenge_deadline)} /><StatLine label="Current generation" value={bundle.caseData.data.generation + 1} detail="of 3 maximum" /><StatLine label="Grounds allowed" value="2" detail="bounded reason codes" /></div><Panel eyebrow="ELIGIBLE ACTIONS" title="Choose a constitutional ground"><div className="challenge-options"><label className={`challenge-option ${ground === "NEW_ADMISSIBLE_EVIDENCE" ? "selected" : ""}`}><input type="radio" checked={ground === "NEW_ADMISSIBLE_EVIDENCE"} onChange={() => setGround("NEW_ADMISSIBLE_EVIDENCE")} /><span><strong>NEW_ADMISSIBLE_EVIDENCE</strong><small>Materially new evidence that satisfies the frozen authority and timing policy.</small></span></label><label className={`challenge-option ${ground === "PROCEDURAL_VIOLATION" ? "selected" : ""}`}><input type="radio" checked={ground === "PROCEDURAL_VIOLATION"} onChange={() => setGround("PROCEDURAL_VIOLATION")} /><span><strong>PROCEDURAL_VIOLATION</strong><small>One of the bounded semantic or evidence constitution violations.</small></span></label></div>{ground === "PROCEDURAL_VIOLATION" && <Field label="Reason code"><select value={reason} onChange={(event) => setReason(event.target.value)}><option>SEMANTIC_BOUNDARY_VIOLATION</option><option>EVIDENCE_ROOT_MISMATCH</option><option>AUTHORITY_BINDING_VIOLATION</option><option>INVALID_STATE_TRANSITION</option></select></Field>}<div className="sticky-action-bar"><TransactionButton label="Submit procedural challenge" action={{ type: "challenge", caseId: id, ground, evidenceId: "EVID-00000003", proceduralReason: reason }} postcondition="challenge_opened" disabled={challenged} onConfirmed={() => setChallenged(true)} />{challenged && <span className="tx-success">Challenge accepted for readjudication</span>}<TransactionButton label="Readjudicate" action={{ type: "readjudicate", caseId: id }} postcondition="readjudicated" disabled={!challenged || readjudicated} onConfirmed={() => setReadjudicated(true)} />{readjudicated && <span className="tx-success">Readjudication complete</span>}<TransactionButton label="Finalize case" action={{ type: "finalize_case", caseId: id }} postcondition="case_final" disabled={!readjudicated || finalized} onConfirmed={() => setFinalized(true)} />{finalized && <span className="tx-success">Final resolution</span>}</div></Panel></>}</StateMessage></Page>;
}
